/**
 * Higher Apps' hint ladders, keyed by paper label. GENERATED by
 * scripts/emit-paper-plan-higher.ts --course higherapps from the authored moves in
 * docs/course-markschemes/higherapps-*-hints.json and the marking instructions in
 * reference/HigherApps_Markschemes (untracked). Do not edit by hand.
 *
 * Its own file because labels collide across courses. No imports, so a hint
 * costs one fetch and not the engine.
 */
export interface CoursePlan {
  /** What the question is asking the pupil to do. */
  skill: string;
  /** How the marks go, in one line. */
  method: string;
  /** Two to six moves, each worth at most 2 marks, in the order they are done. */
  moves: string[];
  /** What each move is worth. */
  marks: number[];
  /** The working as each move begins, or null where it is withheld. */
  shows: (string | null)[];
  /** One thing pupils get wrong here, from the scheme's notes, under move `at`. */
  watch?: { at: number; text: string };
}

